<section class="detail-page"><div class="container"><div class="detail-heading"><div><p class="breadcrumb-text"><a href="<?= e(url('/')) ?>">Khám phá</a> / <?= e($listing['city']) ?></p><h1><?= e($listing['title']) ?></h1><p>★ <?= number_format(array_sum(array_column($listing['reviews'],'rating'))/max(1,count($listing['reviews'])),1) ?> · <?= count($listing['reviews']) ?> đánh giá · <?= e($listing['address']) ?></p></div><button class="btn btn-ghost" type="button" data-share>Chia sẻ</button></div><?php $photos = array_slice($listing['photos'], 0, 3); if (!$photos) { $photos = [['image_url' => null, 'alt_text' => 'Chỗ ở chưa có ảnh']]; } ?>
<div class="photo-grid photo-grid-<?= count($photos) ?>"><?php /* Display demo provenance without claiming these are real property photographs. */ ?><?php foreach($photos as $i=>$photo): ?><img class="photo-<?= $i+1 ?>" src="<?= e(image_url($photo['image_url'])) ?>" alt="<?= e($photo['alt_text']) ?>"><?php endforeach; ?></div><?php if(array_filter($listing['photos'], fn($photo) => str_starts_with($photo['image_url'], '/assets/images/demo/'))): ?><p class="text-muted small mt-2">Ảnh minh họa cho dữ liệu demo, không phải ảnh xác minh của cơ sở lưu trú.</p><?php endif; ?><div class="row mt-5"><div class="col-lg-8 pr-lg-5"><h2><?= e($listing['property_type']) ?> do <?= e($listing['host_name']) ?> đón tiếp</h2><p class="text-muted"><?= (int)$listing['max_guests'] ?> khách · <?= (int)$listing['bedroom_count'] ?> phòng ngủ · <?= (int)$listing['bed_count'] ?> giường</p><p class="lead-copy"><?= nl2br(e($listing['description'])) ?></p><hr><h2>Nơi này có gì?</h2><div class="amenity-grid"><?php foreach($listing['amenities'] as $amenity): ?><span>✓ <?= e($amenity['name']) ?></span><?php endforeach; ?></div><hr><h2>Nội quy và chính sách</h2><p>Nhận phòng từ <?= e(substr($listing['check_in_time'],0,5)) ?> · Trả phòng trước <?= e(substr($listing['check_out_time'],0,5)) ?></p><p><?= $listing['allows_pets']?'Cho phép':'Không cho phép' ?> thú cưng · <?= $listing['allows_smoking']?'Cho phép':'Không cho phép' ?> hút thuốc · <?= $listing['allows_parties']?'Cho phép':'Không cho phép' ?> tiệc</p><p><strong><?= e($listing['cancellation_name']) ?>:</strong> <?= e($listing['cancellation_description']) ?></p><?php if($listing['reviews']): ?><hr><h2>Đánh giá</h2><?php foreach($listing['reviews'] as $review): ?><article class="review"><strong><?= e($review['guest_name']) ?> · <?= str_repeat('★',(int)$review['rating']) ?></strong><p><?= e($review['comment']) ?></p></article><?php endforeach; ?><?php endif; ?></div><div class="col-lg-4"><aside class="booking-box"><div class="booking-price"><strong><?= number_format((float)$listing['nightly_price'],0,',','.') ?>đ</strong> / đêm</div><form method="post" action="<?= e(url('/listings/'.$listing['id'].'/book')) ?>" data-booking-form data-quote-url="<?= e(url('/api/listings/'.$listing['id'].'/quote')) ?>"><?= csrf_field() ?><div class="form-row"><div class="form-group col-6"><label for="check_in">Nhận phòng</label><input class="form-control" id="check_in" type="date" name="check_in" min="<?= date('Y-m-d') ?>" required></div><div class="form-group col-6"><label for="check_out">Trả phòng</label><input class="form-control" id="check_out" type="date" name="check_out" min="<?= date('Y-m-d',strtotime('+1 day')) ?>" required></div></div><div class="form-group"><label for="guests">Số khách</label><input class="form-control" id="guests" type="number" name="guests" min="1" max="<?= (int)$listing['max_guests'] ?>" value="1" required></div><div class="quote-panel" data-quote><span>Chọn ngày để xem tổng tiền</span></div><?php if(\Core\Auth::check()): ?><button class="btn btn-primary btn-block" type="submit">Gửi yêu cầu đặt chỗ</button><?php else: ?><a class="btn btn-primary btn-block" href="<?= e(url('/login')) ?>">Đăng nhập để đặt chỗ</a><?php endif; ?><small>Bạn chưa bị tính phí. Tổng tiền được xác nhận lại trên máy chủ.</small></form></aside></div></div></div></section>

